class Solution:
    def maxValueOfCoins(self, piles: list[list[int]], k: int) -> int:
        n = len(piles)
        dp = [0] * (k + 1)
        for pile in piles:
            prefix = [0]
            for coin in pile:
                prefix.append(prefix[-1] + coin)
            new_dp = [0] * (k + 1)
            for j in range(k + 1):
                for t in range(min(len(pile), j) + 1):
                    new_dp[j] = max(new_dp[j], dp[j - t] + prefix[t])
            dp = new_dp
        return dp[k]

